begin;
create table platform.notification_outbox(id uuid primary key default extensions.gen_random_uuid(),event_type text not null,module_key text not null,resource_type text not null,resource_id text not null,scope_type text not null,scope_id text not null,title text not null,body text not null,target_url text not null,dedupe_key text not null unique,created_at timestamptz not null default statement_timestamp(),dispatched_at timestamptz);
alter table platform.notification_outbox enable row level security;alter table platform.notification_outbox force row level security;revoke all on platform.notification_outbox from public,anon,authenticated,service_role;
create or replace function platform_private.stage_notification(p_event_type text,p_module_key text,p_resource_type text,p_resource_id text,p_scope_type text,p_scope_id text,p_title text,p_body text,p_target_url text,p_dedupe_key text) returns void language plpgsql security definer set search_path='' as $$begin if p_module_key not in('conference','reservations','warehouse','platform') or p_event_type !~ '^[a-z0-9_.-]{3,120}$' or p_resource_type !~ '^[a-z0-9_.-]{1,80}$' or p_scope_type !~ '^[a-z0-9_.-]{1,80}$' or char_length(coalesce(p_title,'')) not between 1 and 160 or char_length(coalesce(p_body,'')) not between 1 and 500 or char_length(coalesce(p_target_url,'')) not between 1 and 1000 or char_length(coalesce(p_dedupe_key,'')) not between 1 and 240 then raise exception 'PLATFORM_NOTIFICATION_EVENT_INVALID' using errcode='22023';end if;insert into platform.notification_outbox(event_type,module_key,resource_type,resource_id,scope_type,scope_id,title,body,target_url,dedupe_key)values(p_event_type,p_module_key,p_resource_type,p_resource_id,p_scope_type,p_scope_id,p_title,p_body,p_target_url,p_dedupe_key)on conflict(dedupe_key)do nothing;end$$;
revoke all on function platform_private.stage_notification(text,text,text,text,text,text,text,text,text,text) from public,anon,authenticated,service_role;
create or replace function platform_private.stage_public_registration_submitted_notification(p_request_id uuid,p_event_id uuid,p_reference text,p_public_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from reservations.public_registration_requests r where r.id=p_request_id and r.event_id=p_event_id and r.request_reference=p_reference and r.submit_operation_id=p_operation_id) then raise exception 'PUBLIC_REGISTRATION_NOTIFICATION_SCOPE_INVALID' using errcode='42501';end if;perform platform_private.stage_notification('reservations.public_registration.submitted','reservations','public_registration_request',p_reference,'event',p_event_id::text,'طلب تسجيل جديد','وصل طلب تسجيل جديد ويحتاج للمراجعة.','./#reservations/registration-requests','public-registration:'||p_public_id::text||':'||p_operation_id::text);end$$;
revoke all on function platform_private.stage_public_registration_submitted_notification(uuid,uuid,text,uuid,uuid) from public,anon,authenticated,service_role;
commit;